hold-order.find:
const firstPerMember = new Map<string, Hold>();
for (const hold of open) {
  if (!firstPerMember.has(hold.memberNo)) firstPerMember.set(hold.memberNo, hold);
}
return [...firstPerMember.values()];

hold-order.replace:
const firstPerMember: Record<string, Hold> = {};
for (const hold of open) {
  if (!(hold.memberNo in firstPerMember)) firstPerMember[hold.memberNo] = hold;
}
return Object.values(firstPerMember);
